const industrialModernEras: PersonaEra[] = ['industrial', 'modern', 'contemporary'];
const futureEras: PersonaEra[] = ['near_future', 'far_future'];

const institutionFit = (group: string): PersonaCategoryFit => {
  if (group.startsWith('A.')) return personaFit('weak', {
    strong: ['real_professional', 'medical'],
    usable: ['urban_life', 'workplace'],
    fusion: ['biopunk', 'science_fiction', 'horror'],
    weak: ['fashion_idol', 'wuxia', 'xianxia']
  });
  if (group.startsWith('B.')) return personaFit('weak', {
    strong: ['real_professional', 'institutional'],
    usable: ['historical', 'urban_life', 'workplace'],
    fusion: ['science_fiction', 'cyberpunk'],
    weak: ['fashion_idol', 'romance', 'wasteland']
  });
  if (group.startsWith('C.')) return personaFit('weak', {
    strong: ['noir_crime', 'real_professional'],
    usable: ['urban_life', 'war_military', 'historical'],
    fusion: ['cyberpunk', 'horror'],
    weak: ['romance', 'fashion_idol', 'xianxia']
  });
  if (group.startsWith('D.')) return personaFit('weak', {
    strong: ['real_professional', 'institutional'],
    usable: ['urban_life', 'historical', 'surreal'],
    fusion: ['xianxia', 'science_fiction'],
    weak: ['wasteland', 'fashion_idol', 'war_military']
  });
  if (group.startsWith('E.')) return personaFit('weak', {
    strong: ['real_professional', 'workplace'],
    usable: ['urban_life', 'war_military', 'wasteland'],
    fusion: ['science_fiction', 'cyberpunk'],
    weak: ['romance', 'court', 'xianxia']
  });
  if (group.startsWith('F.')) return personaFit('weak', {
    strong: ['real_professional', 'urban_life'],
    usable: ['workplace', 'romance', 'fashion_idol'],
    fusion: ['cyberpunk', 'surreal'],
    weak: ['court', 'wuxia', 'xianxia']
  });
  if (group.startsWith('G.')) return personaFit('weak', {
    strong: ['real_professional', 'science_fiction'],
    usable: ['biopunk', 'cyberpunk', 'urban_life'],
    fusion: ['posthuman', 'horror'],
    weak: ['court', 'wuxia', 'romance']
  });
  if (group.startsWith('H.')) return personaFit('weak', {
    strong: ['real_professional', 'war_military'],
    usable: ['institutional', 'noir_crime', 'urban_life'],
    fusion: ['wasteland', 'science_fiction'],
    weak: ['romance', 'fashion_idol', 'xianxia']
  });
  if (group.startsWith('I.')) return personaFit('weak', {
    strong: ['real_professional', 'workplace'],
    usable: ['urban_life', 'noir_crime', 'fashion_idol'],
    fusion: ['cyberpunk', 'science_fiction'],
    weak: ['xianxia', 'wasteland', 'court']
  });
  return personaFit('weak', {
    strong: ['real_professional'],
    usable: ['urban_life', 'war_military', 'adventure'],
    fusion: ['wasteland', 'science_fiction'],
    weak: ['fashion_idol', 'court', 'xianxia']
  });
};

